CREATE TABLE [sales].[SalesPayments]([PaymentId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SalesPayments_Id] DEFAULT NEWSEQUENTIALID(),[InvoiceId] UNIQUEIDENTIFIER NOT NULL,[PaymentMethodId] UNIQUEIDENTIFIER NOT NULL,[Amount] DECIMAL(18,2) NOT NULL,[ReferenceNumber] NVARCHAR(100) NULL,[PaymentDate] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_SalesPayments_Date] DEFAULT SYSUTCDATETIME(),[Status] NVARCHAR(20) NOT NULL CONSTRAINT [DF_SalesPayments_Status] DEFAULT 'COMPLETED',[CreatedBy] NVARCHAR(256) NULL,CONSTRAINT [PK_SalesPayments] PRIMARY KEY([PaymentId]),CONSTRAINT [FK_SalesPayments_Invoice] FOREIGN KEY([InvoiceId]) REFERENCES [sales].[SalesInvoices]([InvoiceId]),CONSTRAINT [FK_SalesPayments_Method] FOREIGN KEY([PaymentMethodId]) REFERENCES [sales].[PaymentMethods]([PaymentMethodId]),CONSTRAINT [CK_SalesPayments_Amount] CHECK([Amount]>0),CONSTRAINT [CK_SalesPayments_Status] CHECK([Status] IN('PENDING','COMPLETED','FAILED','REFUNDED')));
